package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import com.fasterxml.jackson.databind.JsonNode;
import junit.framework.TestCase;
import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8cStructureSaveMysqlTest extends TestCase {
    private A1TestFixture fixture;private ControlledWriteService controlled;private StableEffectLedger effects;
    @Override protected void setUp() throws Exception {if(!Boolean.getBoolean("a1.schema.prepared"))throw new IllegalStateException("Prepared isolated B8c schema required");fixture=new A1TestFixture();String module=System.getProperty("a1.module"),sql=new String(Files.readAllBytes(Paths.get(module,"sql","ai_agent_controlled_write_v2.sql")),StandardCharsets.UTF_8);fixture.db.execute(sql.replaceAll("(?m)^--[^\\r\\n]*","").trim());controlled=new ControlledWriteService(new AgentStore(fixture.db),fixture.guard,fixture.workbooks,fixture.versions,fixture.tx.getTransactionManager());for(String name:new String[]{"enabled","b8EffectEnabled","b8StructureEnabled","b8SheetEnabled","b8SheetRenameEnabled","b8SheetCopyEnabled","b8SheetDeleteEnabled"}){Field f=ControlledWriteService.class.getDeclaredField(name);f.setAccessible(true);f.set(controlled,true);}effects=new StableEffectLedger(fixture.db);}
    private ObjectNode baseline(){return (ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Sheet\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"a\",\"t\":1}},\"1\":{\"1\":{\"v\":\"b\",\"t\":1}},\"5\":{\"5\":{\"v\":\"z\",\"t\":1}}},\"rowData\":{},\"columnData\":{},\"mergeData\":[]}}}");}
    private ObjectNode request(long book,String type,boolean force){ObjectNode ws=fixture.runs.workspace(book,1),sheet=(ObjectNode)ws.path("snapshot").path("sheets").path("s");int rows=sheet.path("rowCount").asInt(),cols=sheet.path("columnCount").asInt();ObjectNode req=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",book).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedDraftVersion",ws.path("draftVersion").asLong()).put("expectedBranchVersion",ws.path("branchVersion").asLong()).put("activeSheetId","s").put("overwrite","confirmed");String endCol=cols==6?"F":"G";req.set("writeScopes",arr().add(obj().put("sheetId","s").put("range","A1:"+endCol+rows)));ObjectNode a=obj().put("schemaVersion","2.0").put("type",type).put("count",1);a.set("target",obj().put("sheetId","s"));a.put(type.endsWith("Rows")?(type.startsWith("insert")?"rowIndex":"rowPosition"):(type.startsWith("insert")?"columnIndex":"columnPosition"),2);if(type.startsWith("insert"))a.put("position","at");if(force)a.put("force",true);req.set("actions",arr().add(a));return req;}
    private ObjectNode claim(ObjectNode run){return controlled.claim(run.path("runId").asText(),1,obj().put("transportVersion",2).put("clientId","b8c-test").put("fencingToken",run.path("fencingToken").asLong()));}
    private ObjectNode receipt(ObjectNode m){ObjectNode r=obj().put("transportVersion",2).put("callId",m.path("callId").asText()).put("effectId",m.path("effectId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong()).put("ok",true);r.set("structureReadback",m.path("structureReadback").deepCopy());return r;}
    private void reject(Runnable r){try{r.run();fail("unsafe structure accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testInsertAndDeleteSaveWithDistinctEffects(){long book=fixture.seed(baseline().toString());ObjectNode run=controlled.create(request(book,"insertRows",false),1),m=claim(run),r=receipt(m);ObjectNode forged=r.deepCopy();((ObjectNode)forged.path("structureReadback")).put("rowCount",9);reject(()->controlled.receipt(run.path("runId").asText(),1,forged));assertNull(fixture.status(book).get("workingState"));ObjectNode saved=controlled.receipt(run.path("runId").asText(),1,r);assertEquals("COMPLETED",saved.path("status").asText());controlled.receipt(run.path("runId").asText(),1,r);effects.assertStatus(m.path("effectId").asText(),run.path("runId").asText(),m.path("callId").asText(),"PERSISTED");assertEquals(7,fixture.runs.workspace(book,1).path("snapshot").path("sheets").path("s").path("rowCount").asInt());ObjectNode split=controlled.create(request(book,"deleteRows",true),1),splitM=claim(split),done=controlled.receipt(split.path("runId").asText(),1,receipt(splitM));assertEquals("COMPLETED",done.path("status").asText());assertEquals(6,fixture.runs.workspace(book,1).path("snapshot").path("sheets").path("s").path("rowCount").asInt());assertEquals("b",fixture.runs.workspace(book,1).path("snapshot").path("sheets").path("s").path("cellData").path("1").path("1").path("v").asText());}
    public void testDeleteRequiresForceAndFailureIsUnknown(){long book=fixture.seed(baseline().toString());reject(()->controlled.create(request(book,"deleteColumns",false),1));ObjectNode run=controlled.create(request(book,"deleteColumns",true),1),m=claim(run),failed=receipt(m);failed.remove("structureReadback");failed.put("ok",false).put("error","connection lost after SDK call");ObjectNode unknown=controlled.receipt(run.path("runId").asText(),1,failed);assertEquals("PAUSED",unknown.path("status").asText());assertNull(fixture.status(book).get("workingState"));effects.assertStatus(m.path("effectId").asText(),run.path("runId").asText(),m.path("callId").asText(),"UNKNOWN");reject(()->controlled.receipt(run.path("runId").asText(),1,receipt(m)));}
    public void testCreateSheetStableEffectAndSavedFact(){long book=fixture.seed(baseline().toString());ObjectNode req=request(book,"insertRows",false),action=obj().put("schemaVersion","2.0").put("type","createSheet").put("newSheetName","Generated").put("rowCount",6).put("columnCount",6);action.set("target",obj().put("sheetId","s"));req.set("actions",arr().add(action));ObjectNode run=controlled.create(req,1),manifest=claim(run);String newId=manifest.path("structurePatch").path("newSheetId").asText();assertTrue(newId.startsWith("ai-"));ObjectNode secondClaim=claim(run);assertEquals(false,secondClaim.path("replayAllowed").asBoolean());ObjectNode saved=controlled.receipt(run.path("runId").asText(),1,receipt(manifest));assertEquals("COMPLETED",saved.path("status").asText());controlled.receipt(run.path("runId").asText(),1,receipt(manifest));effects.assertStatus(manifest.path("effectId").asText(),run.path("runId").asText(),manifest.path("callId").asText(),"PERSISTED");JsonNode state=fixture.runs.workspace(book,1).path("snapshot");assertEquals(newId,state.path("sheetOrder").get(1).asText());assertEquals("Generated",state.path("sheets").path(newId).path("name").asText());assertEquals("a",state.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());}
    public void testCopySheetStableEffectAndSavedFact(){long book=fixture.seed(baseline().toString());ObjectNode req=request(book,"insertRows",false),action=obj().put("schemaVersion","2.0").put("type","copySheet").put("newSheetName","Generated");action.set("target",obj().put("sheetId","s"));req.set("actions",arr().add(action));ObjectNode run=controlled.create(req,1),manifest=claim(run);String newId=manifest.path("structurePatch").path("newSheetId").asText();assertTrue(newId.startsWith("ai-"));ObjectNode secondClaim=claim(run);assertEquals(false,secondClaim.path("replayAllowed").asBoolean());ObjectNode saved=controlled.receipt(run.path("runId").asText(),1,receipt(manifest));assertEquals("COMPLETED",saved.path("status").asText());controlled.receipt(run.path("runId").asText(),1,receipt(manifest));effects.assertStatus(manifest.path("effectId").asText(),run.path("runId").asText(),manifest.path("callId").asText(),"PERSISTED");JsonNode state=fixture.runs.workspace(book,1).path("snapshot");assertEquals(newId,state.path("sheetOrder").get(1).asText());assertEquals("Generated",state.path("sheets").path(newId).path("name").asText());assertEquals("a",state.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());}
    public void testRenameSheetSavedWithStableEffect(){long book=fixture.seed(baseline().toString());ObjectNode req=request(book,"insertRows",false),action=obj().put("schemaVersion","2.0").put("type","renameSheet").put("newSheetName","Renamed");action.set("target",obj().put("sheetId","s"));req.set("actions",arr().add(action));ObjectNode run=controlled.create(req,1),manifest=claim(run),saved=controlled.receipt(run.path("runId").asText(),1,receipt(manifest));assertEquals("COMPLETED",saved.path("status").asText());controlled.receipt(run.path("runId").asText(),1,receipt(manifest));effects.assertStatus(manifest.path("effectId").asText(),run.path("runId").asText(),manifest.path("callId").asText(),"PERSISTED");JsonNode state=fixture.runs.workspace(book,1).path("snapshot");assertEquals("Renamed",state.path("sheets").path("s").path("name").asText());assertEquals("a",state.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());}
    public void testDeleteSheetSaveAndRepeatReceipt(){long book=fixture.seed(B8cDeleteSheetManifestTest.snapshot().toString());ObjectNode req=request(book,"insertRows",false);req.set("actions",arr().add(B8cDeleteSheetManifestTest.action()));ObjectNode run=controlled.create(req,1),m=claim(run),r=receipt(m),forged=r.deepCopy();((ObjectNode)forged.path("structureReadback")).put("activeSheetId","s");reject(()->controlled.receipt(run.path("runId").asText(),1,forged));assertNull(fixture.status(book).get("workingState"));ObjectNode saved=controlled.receipt(run.path("runId").asText(),1,r);assertEquals("COMPLETED",saved.path("status").asText());controlled.receipt(run.path("runId").asText(),1,r);effects.assertStatus(m.path("effectId").asText(),run.path("runId").asText(),m.path("callId").asText(),"PERSISTED");JsonNode snap=fixture.runs.workspace(book,1).path("snapshot");assertFalse(snap.path("sheets").has("s"));assertEquals("keep",snap.path("activeSheet").asText());assertEquals("kept",snap.path("sheets").path("keep").path("cellData").path("0").path("0").path("v").asText());}
    public void testDeleteSheetUnknownNeverReplays(){long book=fixture.seed(B8cDeleteSheetManifestTest.snapshot().toString());ObjectNode req=request(book,"insertRows",false);req.set("actions",arr().add(B8cDeleteSheetManifestTest.action()));ObjectNode run=controlled.create(req,1),m=claim(run),r=receipt(m);r.remove("structureReadback");r.put("ok",false).put("error","connection lost after delete");assertEquals("PAUSED",controlled.receipt(run.path("runId").asText(),1,r).path("status").asText());reject(()->claim(run));reject(()->controlled.receipt(run.path("runId").asText(),1,receipt(m)));assertNull(fixture.status(book).get("workingState"));}
    public void testOverflowIndexRejectedBeforeAnyWrite(){long book=fixture.seed(baseline().toString());ObjectNode req=request(book,"insertRows",false);((ObjectNode)req.path("actions").get(0)).put("rowIndex",4294967298L);reject(()->controlled.create(req,1));assertEquals(0,fixture.db.queryForObject("select count(*) from ai_agent_run where workbook_id=?",Integer.class,book).intValue());assertNull(fixture.status(book).get("workingState"));assertEquals(0,fixture.db.queryForObject("select count(*) from ai_agent_effect e join ai_agent_run r on e.run_id=r.run_id where r.workbook_id=?",Integer.class,book).intValue());}
}
